using System;using System.Linq;using System.IO;using System.Text;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using Game.ThirdPerson;
public static class PlayerFixValidation {
static string PathOf(Transform t){return t.parent?PathOf(t.parent)+"/"+t.name:t.name;}
[MenuItem("Tools/Characters/Audit Player Fixes")]
public static void Audit(){var s=new StringBuilder();var scene=SceneManager.GetActiveScene();var m=UnityEngine.Object.FindAnyObjectByType<ThirdPersonMotor>();s.AppendLine("scene="+scene.path+" player="+m.transform.position);s.AppendLine("motion="+m.GetComponentsInChildren<UntitledCharacterMotion>(true).Length+" retarget="+m.GetComponentsInChildren<BlenderCharacterRetarget>(true).Length+" mesh="+m.GetComponentsInChildren<SkinnedMeshRenderer>(true).Length);foreach(var c in UnityEngine.Object.FindObjectsByType<Canvas>()){s.AppendLine("CANVAS "+PathOf(c.transform));foreach(var t in c.GetComponentsInChildren<RectTransform>(true))s.AppendLine(t.gameObject.activeInHierarchy+" "+PathOf(t));}s.AppendLine("camera="+m.cameraTransform.position+" target="+m.cameraTransform.GetComponent<ThirdPersonFollowCamera>().target.position+" visual="+m.visualRoot.position);foreach(var skin in m.GetComponentsInChildren<SkinnedMeshRenderer>(true)){s.AppendLine("SKIN "+skin.name+" bounds="+skin.localBounds);for(int i=0;i<skin.sharedMesh.blendShapeCount;i++)s.AppendLine("SHAPE "+skin.sharedMesh.GetBlendShapeName(i));}var rs=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<MeshRenderer>(true)).Where(r=>r.enabled&&r.gameObject.activeInHierarchy&&!r.transform.IsChildOf(m.transform));s.AppendLine("renderers="+rs.Count()+" colliders="+UnityEngine.Object.FindObjectsByType<Collider>().Length);foreach(var r in rs.Where(r=>!r.GetComponentInParent<LODGroup>()&&!r.GetComponentInParent<Collider>()&&r.GetComponent<MeshFilter>()&&r.bounds.size.y>1).Take(100))s.AppendLine("NO_LOD_COLLIDER "+PathOf(r.transform)+" "+r.bounds);File.WriteAllText(Application.dataPath+"/../Logs/PlayerFixAudit.txt",s.ToString());Debug.Log("PLAYER_FIX_AUDIT saved");}
static void CheckSpawn(ThirdPersonMotor m){var cc=m.GetComponent<CharacterController>();Physics.SyncTransforms();Func<Vector3,bool> clear=point=>{var center=point+cc.center;float half=cc.height*.5f-cc.radius;return !Physics.OverlapCapsule(center+Vector3.up*half,center-Vector3.up*half,cc.radius+.03f,~0,QueryTriggerInteraction.Ignore).Any(c=>!c.transform.IsChildOf(m.transform));};if(clear(m.transform.position)){Debug.Log("PLAYER_SPAWN_CLEAR "+m.transform.position);return;}var origin=m.transform.position;for(int ring=1;ring<30;ring++)for(int a=0;a<16;a++){var sample=origin+new Vector3(Mathf.Cos(a*Mathf.PI/8),0,Mathf.Sin(a*Mathf.PI/8))*ring*3;foreach(var h in Physics.RaycastAll(new Vector3(sample.x,1000,sample.z),Vector3.down,2000,~0,QueryTriggerInteraction.Ignore).OrderBy(h=>h.distance)){if(!(h.collider is TerrainCollider)||h.normal.y<.8f)continue;var pos=h.point+Vector3.up*.06f;if(!clear(pos))continue;cc.enabled=false;m.transform.position=pos;Physics.SyncTransforms();cc.enabled=true;m.cameraTransform.GetComponent<ThirdPersonFollowCamera>().UpdateView(1);Debug.Log("PLAYER_SPAWN_REPAIRED "+pos);return;}}throw new Exception("Cannot find unobstructed spawn");}
[MenuItem("Tools/Characters/Finish Player Fixes")] public static void Finish(){if(EditorApplication.isPlaying)throw new Exception("Stop play first");foreach(var c in UnityEngine.Object.FindObjectsByType<Canvas>()){c.gameObject.SetActive(false);if(PrefabUtility.IsPartOfPrefabInstance(c.gameObject))PrefabUtility.RecordPrefabInstancePropertyModifications(c.gameObject);}var m=UnityEngine.Object.FindAnyObjectByType<ThirdPersonMotor>();m.GetComponentInChildren<CharacterGroundAndLook>().maxFootAdjustment=.6f;CheckSpawn(m);PrefabUtility.SaveAsPrefabAsset(m.gameObject,"Assets/Game/Prefabs/FurinaPlayer.prefab");EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());AssetDatabase.SaveAssets();Debug.Log("PLAYER_FIXES_SAVED");}
[MenuItem("Tools/Characters/Reload Verify Player Fixes")] public static void Reload(){if(EditorApplication.isPlaying)throw new Exception("Stop play");var path=SceneManager.GetActiveScene().path;EditorSceneManager.OpenScene(path);var m=UnityEngine.Object.FindAnyObjectByType<ThirdPersonMotor>();var cam=m.cameraTransform.GetComponent<Camera>();if(cam.useOcclusionCulling)throw new Exception("Occlusion override did not persist");if(UnityEngine.Object.FindObjectsByType<Canvas>().Length>0)throw new Exception("Demo UI reactivated");var cols=UnityEngine.Object.FindObjectsByType<MeshCollider>().Count(c=>c.name=="Static Collision");if(cols<3900||m.GetComponentsInChildren<BlenderCharacterRetarget>(true).Length!=1||m.GetComponentsInChildren<UntitledCharacterMotion>(true).Length!=1)throw new Exception("Player or collisions missing");Audit();Debug.Log("PLAYER_FIX_RELOAD_PASS staticColliders="+cols+" UI=0 occlusion=false");}
[MenuItem("Tools/Characters/Player Front View")]
public static void Front(){var m=UnityEngine.Object.FindAnyObjectByType<ThirdPersonMotor>();var c=m.cameraTransform.GetComponent<ThirdPersonFollowCamera>();c.enabled=false;c.yaw=m.visualRoot.eulerAngles.y+180;c.pitch=5;c.distance=1.9f;c.UpdateView(1);}
[MenuItem("Tools/Characters/Test Object Collision")]
public static void Collision(){if(!EditorApplication.isPlaying)throw new Exception("Play mode required");var m=UnityEngine.Object.FindAnyObjectByType<ThirdPersonMotor>();var cc=m.GetComponent<CharacterController>();var saved=m.transform.position;bool on=m.enabled;m.enabled=false;bool found=false;try{foreach(var col in UnityEngine.Object.FindObjectsByType<MeshCollider>().Where(c=>c.enabled&&c.name=="Static Collision"&&c.bounds.size.y>2&&c.bounds.size.x>1&&c.bounds.size.z>1).OrderBy(c=>(c.bounds.center-saved).sqrMagnitude)){var b=col.bounds;foreach(var dir in new[]{Vector3.forward,Vector3.back,Vector3.left,Vector3.right}){var ray=new Ray(b.center+dir*(b.extents.magnitude+3),-dir);if(!col.Raycast(ray,out var hit,b.extents.magnitude*2+6)||Mathf.Abs(hit.normal.y)>.15f)continue;var normal=Vector3.ProjectOnPlane(hit.normal,Vector3.up).normalized;var center=hit.point+normal*1.5f;float half=Mathf.Max(0,cc.height*.5f-cc.radius);if(Physics.OverlapCapsule(center+Vector3.up*half,center-Vector3.up*half,cc.radius+.05f,~0,QueryTriggerInteraction.Ignore).Any(c=>c!=cc))continue;cc.enabled=false;m.transform.position=center-Vector3.up*cc.center.y;Physics.SyncTransforms();cc.enabled=true;CollisionFlags flags=CollisionFlags.None;for(int i=0;i<120;i++)flags|=cc.Move(-normal*.03f);float separation=Vector3.Dot((m.transform.position+Vector3.up*cc.center.y)-hit.point,normal);bool pass=separation>cc.radius-.06f&&separation<1.5f&&(flags&CollisionFlags.Sides)!=0;Debug.Log("PLAYER_COLLISION_TEST pass="+pass+" separation="+separation+" radius="+cc.radius+" object="+PathOf(col.transform));if(!pass)throw new Exception("Character crossed solid surface");found=true;break;}if(found)break;}if(!found)throw new Exception("No vertical solid found");}finally{cc.enabled=false;m.transform.position=saved;Physics.SyncTransforms();cc.enabled=true;m.enabled=on;}}
[MenuItem("Tools/Characters/Player Right View")] public static void Right(){var m=UnityEngine.Object.FindAnyObjectByType<ThirdPersonMotor>();var c=m.cameraTransform.GetComponent<ThirdPersonFollowCamera>();c.enabled=false;c.yaw=m.visualRoot.eulerAngles.y+90;c.pitch=12;c.distance=3.2f;c.UpdateView(1);}
[MenuItem("Tools/Characters/Player Left View")] public static void Left(){var m=UnityEngine.Object.FindAnyObjectByType<ThirdPersonMotor>();var c=m.cameraTransform.GetComponent<ThirdPersonFollowCamera>();c.enabled=false;c.yaw=m.visualRoot.eulerAngles.y-90;c.pitch=12;c.distance=3.2f;c.UpdateView(1);}
[MenuItem("Tools/Characters/Test Original Motions")]
public static void Motion(){if(!EditorApplication.isPlaying)throw new Exception("Play mode required");var m=UnityEngine.Object.FindAnyObjectByType<ThirdPersonMotor>();var rig=m.GetComponentInChildren<UntitledCharacterMotion>();var bone=m.GetComponentInChildren<BlenderCharacterRetarget>().GetComponentsInChildren<Transform>().First(t=>t.name=="Left leg");var startRot=bone.localRotation;float blinkPeak=0;var pos=m.transform.position;var cam=m.cameraTransform.GetComponent<ThirdPersonFollowCamera>();float dist=cam.distance;cam.Zoom(1);bool first=cam.IsFirstPerson;cam.distance=dist;cam.UpdateView(1);m.SimulationInput=true;int frame=Time.frameCount;double start=EditorApplication.timeSinceStartup;float delta=0,peak=pos.y;bool jumped=false;EditorApplication.CallbackFunction update=null;update=()=>{float t=(float)(EditorApplication.timeSinceStartup-start);if(t<4){m.SimulatedMove=Vector2.up;m.SimulatedSprint=t>2;}else{m.SimulatedMove=Vector2.zero;if(!jumped){m.SimulatedJump=true;jumped=true;}}blinkPeak=Mathf.Max(blinkPeak,rig.BlinkWeight);delta=Mathf.Max(delta,Quaternion.Angle(startRot,bone.localRotation));peak=Mathf.Max(peak,m.transform.position.y);if(t<8)return;EditorApplication.update-=update;m.SimulationInput=false;Debug.Log("ORIGINAL_MOTION_TEST frames="+(Time.frameCount-frame)+" displacement="+Vector3.Distance(pos,m.transform.position)+" grounded="+m.Grounded+" heightDelta="+(peak-pos.y)+" legDegrees="+delta+" joints="+rig.joints.Length+" blink="+blinkPeak+" firstPerson="+first);};EditorApplication.update+=update;}
}






